"""Per-operating-level linear Gaussian model for y.

x[0] takes 9 well-separated levels; k = int(x[0] - 0.7) indexes them (0..8).
Within a level, mean = linear in a compression-efficiency feature
e = log(x12 / x11) / (x9 - x8) and in x9, x4, x10, x13, x2,
plus a globally shared slope on x7; the mean is clamped to [0.9515, 0.9985]
(y is bounded to about [0.95, 1.0]); sd is level-specific.
"""
from adr.dist import Normal, log, maximum, minimum


def model(x):
    k = int(x[0] - 0.7)
    t = ((((3.0472576628657966, 63.925028297556835, -0.0011674464718058409, -0.0001365480972305988, 0.17134780048581888, -1.06301106746605), (4.985623455411314e-06, 0.0044285583366713895)), ((-0.9360650490241176, 34.971281155808846, -0.0013310866518489632, -0.00015992512643283642, 0.10376381194016915, 3.373395855642322), (6.914806526481243e-06, 0.0033804188490832465)), ((2.487529843548047, 13.284508771345267, -0.0020423289637834514, -0.0001675394995504602, -0.003011492847639019, 0.8527594211748983), (1.1355373885635345e-07, 0.0025274603392968446))),
         (((1.6265714621263176, 24.45172861185342, -0.0014029370017791221, -0.00018751961187084276, 0.008420508356888234, 1.545748642407391), (-4.870031489190296e-08, 0.0025545390070312196)), ((0.9976972864464364, 131.63693629436446, -8.844819733217196e-05, -0.00013426548806383387, 0.05987441259820514, 0.2507751242675338), (5.900669464153907e-08, 0.0033792763682305273)), ((-0.37964994175779226, 168.0016192884682, 0.0005916915499354514, -0.00016399244207510044, 0.04230792089797042, 1.2396858004605655), (2.619035228690336e-07, 0.0033378926281813974))),
         (((-2.044099388668287, 162.86702716959482, 0.000601724558635032, -4.465058356117879e-05, 0.05355856605824272, 1.814732421184392), (-1.989560161064219e-08, 0.002479737217692992)), ((-1.7195467835226503, 178.52847326605382, 0.00044530867131645224, -2.9399210710323587e-05, 0.04749580079669613, 1.3861179991134125), (1.959159279252276e-07, 0.0021862840341583603)), ((-1.075093900356124, 126.05229622296116, 8.731988418134162e-05, -3.2460392077382494e-05, 0.04039406794925071, 1.4394210542347032), (-2.274714212546769e-07, 0.001517369743675151))))[k // 3][k % 3]
    c = t[0]
    e = log(x[12] / x[11]) / (x[9] - x[8])
    m = (c[0] + c[1] * e + c[2] * x[9] + c[3] * x[4] + c[4] * x[10] + c[5] * x[13]
         + t[1][0] * x[2] + -0.00016842403498174008 * x[7])
    return Normal(minimum(maximum(m, 0.9515), 0.9985), t[1][1])
